CONFIG = {"base_url": "https://busbook.example.test", "current_date": "2024-02-10", "current_time": "08:00"}


class _Store:
    """In-memory stand-in for the application's database."""

    def __init__(self):
        self.users = {
            "testuser@example.com": {"email": "testuser@example.com", "password": "Test@1234", "name": "Test User"}
        }
        self.buses = {
            "BUS001": {"bus_id": "BUS001", "name": "Volvo AC Sleeper 9:00 AM", "route": "Mumbai to Pune", 
                      "departure": "09:00", "arrival": "13:00", "fare": 850.00, "total_seats": 40},
            "BUS002": {"bus_id": "BUS002", "name": "Scania Multi-Axle 11:30 PM", "route": "Mumbai to Pune",
                      "departure": "23:30", "arrival": "03:30", "fare": 950.00, "total_seats": 45},
            "BUS003": {"bus_id": "BUS003", "name": "Mercedes Luxury 10:30 AM", "route": "Bangalore to Chennai",
                      "departure": "10:30", "arrival": "17:00", "fare": 1200.00, "total_seats": 36},
            "BUS004": {"bus_id": "BUS004", "name": "Ashok Leyland Sleeper 14:00 PM", "route": "Delhi to Jaipur",
                      "departure": "14:00", "arrival": "19:00", "fare": 650.00, "total_seats": 40}
        }
        self.pre_booked_seats = {("BUS002", "15B", "2024-02-15")}
        self.bookings = {}
        self.cards = {
            "4111111111111111": {"card_number": "4111111111111111", "balance": 50000.00, "valid": True},
            "5555555555554444": {"card_number": "5555555555554444", "balance": 200.00, "valid": True}
        }
        self._next_pnr = 1000000000

    def generate_pnr(self):
        pnr = f"PNR{self._next_pnr}"
        self._next_pnr += 1
        return pnr

    def is_seat_occupied(self, bus_id, seat_number, travel_date):
        if (bus_id, seat_number, travel_date) in self.pre_booked_seats:
            return True
        for booking in self.bookings.values():
            if (booking["bus_id"] == bus_id and booking["seat_number"] == seat_number 
                and booking["travel_date"] == travel_date):
                return True
        return False

    def create_booking(self, bus_id, travel_date, seat_number, passenger_name, age, gender, contact, fare):
        pnr = self.generate_pnr()
        self.bookings[pnr] = {
            "pnr": pnr,
            "bus_id": bus_id,
            "travel_date": travel_date,
            "seat_number": seat_number,
            "passenger_name": passenger_name,
            "age": age,
            "gender": gender,
            "contact": contact,
            "fare": fare,
            "status": "Confirmed"
        }
        return pnr

    def delete_booking(self, pnr):
        if pnr in self.bookings:
            del self.bookings[pnr]
            return True
        return False

    def get_all_seats(self, bus_id):
        bus = self.buses.get(bus_id)
        if not bus:
            return []
        total_seats = bus["total_seats"]
        seats = []
        # Generate seats column-first: 1A, 2A, 3A, ..., then 1B, 2B, 3B, ..., etc.
        # Assume 4 columns (A, B, C, D) for layout
        num_columns = 4
        rows_per_column = (total_seats + num_columns - 1) // num_columns

        for col_index in range(num_columns):
            col = chr(ord('A') + col_index)
            for row in range(1, rows_per_column + 1):
                seat_index = col_index * rows_per_column + row
                if seat_index <= total_seats:
                    seats.append(f"{row}{col}")

        return seats


DB = _Store()
_SESSION = {
    "logged_in_email": None,
    "page": "Login Page",
    "message": "",
    "search_results": [],
    "selected_bus": None,
    "selected_seat": None,
    "travel_date": None,
    "passenger_details": None,
    "last_booking": None
}


def _parse_route(route):
    parts = route.split(" to ")
    if len(parts) == 2:
        return parts[0].strip(), parts[1].strip()
    return None, None


def _match_route(bus_route, source, destination):
    bus_source, bus_dest = _parse_route(bus_route)
    if bus_source and bus_dest:
        return (bus_source.lower() == source.lower().strip() and 
                bus_dest.lower() == destination.lower().strip())
    return False


def _time_to_minutes(time_str):
    parts = time_str.split(":")
    return int(parts[0]) * 60 + int(parts[1])


class UI:
    """UI-layer actions - what the user does and sees in the portal."""

    @staticmethod
    def current_page():
        return _SESSION["page"]

    @staticmethod
    def visible_message():
        return _SESSION["message"]

    @staticmethod
    def navigate_to_login():
        _SESSION["page"] = "Login Page"
        _SESSION["message"] = ""

    @staticmethod
    def login(email, password):
        user = DB.users.get(email)
        if user and user["password"] == password:
            _SESSION["logged_in_email"] = email
            _SESSION["page"] = "Search Page"
            _SESSION["message"] = ""
            return True
        else:
            _SESSION["message"] = "Invalid email or password. Please try again."
            _SESSION["page"] = "Login Page"
            return False

    @staticmethod
    def search_buses(source, destination, travel_date):
        if not _SESSION["logged_in_email"]:
            return False

        if travel_date < CONFIG["current_date"]:
            _SESSION["message"] = "Please select a current or future date."
            return False

        results = []
        for bus in DB.buses.values():
            if _match_route(bus["route"], source, destination):
                if travel_date == CONFIG["current_date"]:
                    if _time_to_minutes(bus["departure"]) > _time_to_minutes(CONFIG["current_time"]):
                        results.append(bus)
                else:
                    results.append(bus)

        if not results:
            _SESSION["message"] = "No buses available for this route on the selected date."
            return False

        _SESSION["search_results"] = results
        _SESSION["travel_date"] = travel_date
        _SESSION["page"] = "Search Results Page"
        _SESSION["message"] = ""
        return True

    @staticmethod
    def get_search_results():
        if _SESSION["page"] != "Search Results Page":
            return []
        return [{"bus_id": b["bus_id"], "name": b["name"], "route": b["route"],
                 "departure": b["departure"], "arrival": b["arrival"], "fare": b["fare"]}
                for b in _SESSION["search_results"]]

    @staticmethod
    def select_bus(bus_name):
        if _SESSION["page"] != "Search Results Page":
            return False

        for bus in _SESSION["search_results"]:
            if bus["name"] == bus_name:
                _SESSION["selected_bus"] = bus
                _SESSION["page"] = "Seat Selection Page"
                _SESSION["message"] = ""
                return True

        _SESSION["message"] = "Bus not found in search results."
        return False

    @staticmethod
    def get_seat_map():
        if _SESSION["page"] != "Seat Selection Page" or not _SESSION["selected_bus"]:
            return []

        bus_id = _SESSION["selected_bus"]["bus_id"]
        travel_date = _SESSION["travel_date"]
        all_seats = DB.get_all_seats(bus_id)

        seat_map = []
        for seat in all_seats:
            status = "occupied" if DB.is_seat_occupied(bus_id, seat, travel_date) else "available"
            seat_map.append({"seat_number": seat, "status": status})

        return seat_map

    @staticmethod
    def select_seat(seat_number):
        if _SESSION["page"] != "Seat Selection Page" or not _SESSION["selected_bus"]:
            return False

        bus_id = _SESSION["selected_bus"]["bus_id"]
        travel_date = _SESSION["travel_date"]
        all_seats = DB.get_all_seats(bus_id)

        if seat_number not in all_seats:
            _SESSION["message"] = "Invalid seat number."
            return False

        if DB.is_seat_occupied(bus_id, seat_number, travel_date):
            _SESSION["message"] = "Seat already booked"
            return False

        _SESSION["selected_seat"] = seat_number
        _SESSION["page"] = "Passenger Details Page"
        _SESSION["message"] = ""
        return True

    @staticmethod
    def enter_passenger_details(passenger_name, age, gender, contact):
        if _SESSION["page"] != "Passenger Details Page":
            return False

        if not passenger_name or passenger_name.strip() == "":
            _SESSION["message"] = "Passenger name is required."
            return False

        if age < 1 or age > 120:
            _SESSION["message"] = "Age must be between 1 and 120."
            return False

        if not (isinstance(contact, str) and contact.isdigit() and len(contact) == 10):
            _SESSION["message"] = "Please enter a valid 10-digit mobile number."
            return False

        _SESSION["passenger_details"] = {
            "passenger_name": passenger_name,
            "age": age,
            "gender": gender,
            "contact": contact
        }
        _SESSION["page"] = "Payment Page"
        _SESSION["message"] = ""
        return True

    @staticmethod
    def make_payment(card_number, cvv, expiry):
        if _SESSION["page"] != "Payment Page":
            return False

        card = DB.cards.get(card_number)
        fare = _SESSION["selected_bus"]["fare"]

        if not card or not card["valid"] or card["balance"] < fare:
            _SESSION["message"] = "Payment declined due to insufficient funds."
            return False

        pnr = DB.create_booking(
            _SESSION["selected_bus"]["bus_id"],
            _SESSION["travel_date"],
            _SESSION["selected_seat"],
            _SESSION["passenger_details"]["passenger_name"],
            _SESSION["passenger_details"]["age"],
            _SESSION["passenger_details"]["gender"],
            _SESSION["passenger_details"]["contact"],
            fare
        )

        booking = DB.bookings[pnr]
        _SESSION["last_booking"] = {
            "pnr": pnr,
            "passenger_name": booking["passenger_name"],
            "seat_number": booking["seat_number"],
            "bus_name": _SESSION["selected_bus"]["name"],
            "travel_date": booking["travel_date"],
            "route": _SESSION["selected_bus"]["route"],
            "status": booking["status"]
        }

        _SESSION["page"] = "Booking Confirmation Page"
        _SESSION["message"] = ""
        return True

    @staticmethod
    def get_booking_confirmation():
        if _SESSION["page"] != "Booking Confirmation Page":
            return None
        return dict(_SESSION["last_booking"]) if _SESSION["last_booking"] else None


class API:
    """API-layer actions."""

    @staticmethod
    def api_login(email, password):
        user = DB.users.get(email)
        if user and user["password"] == password:
            return {"ok": True, "user_email": email}
        else:
            return {"ok": False, "error": "Invalid email or password. Please try again."}

    @staticmethod
    def api_search_buses(source, destination, travel_date):
        if travel_date < CONFIG["current_date"]:
            return {"ok": False, "error": "Please select a current or future date."}

        results = []
        for bus in DB.buses.values():
            if _match_route(bus["route"], source, destination):
                if travel_date == CONFIG["current_date"]:
                    if _time_to_minutes(bus["departure"]) > _time_to_minutes(CONFIG["current_time"]):
                        results.append(bus)
                else:
                    results.append(bus)

        if not results:
            return {"ok": False, "error": "No buses available for this route on the selected date."}

        buses = [{"bus_id": b["bus_id"], "name": b["name"], "route": b["route"],
                  "departure": b["departure"], "arrival": b["arrival"], "fare": b["fare"]}
                 for b in results]
        return {"ok": True, "buses": buses}

    @staticmethod
    def api_get_seats(bus_id, travel_date):
        if bus_id not in DB.buses:
            return {"ok": False, "error": "Bus not found."}

        all_seats = DB.get_all_seats(bus_id)
        seats = []
        for seat in all_seats:
            status = "occupied" if DB.is_seat_occupied(bus_id, seat, travel_date) else "available"
            seats.append({"seat_number": seat, "status": status})

        return {"ok": True, "seats": seats}

    @staticmethod
    def api_book_ticket(bus_id, travel_date, seat_number, passenger_name, age, gender, contact, card_number, cvv, expiry):
        if not passenger_name or passenger_name.strip() == "":
            return {"ok": False, "error": "Passenger name is required."}

        if age < 1 or age > 120:
            return {"ok": False, "error": "Age must be between 1 and 120."}

        if not (isinstance(contact, str) and contact.isdigit() and len(contact) == 10):
            return {"ok": False, "error": "Please enter a valid 10-digit mobile number."}

        if bus_id not in DB.buses:
            return {"ok": False, "error": "Bus not found."}

        all_seats = DB.get_all_seats(bus_id)
        if seat_number not in all_seats:
            return {"ok": False, "error": "Invalid seat number."}

        if DB.is_seat_occupied(bus_id, seat_number, travel_date):
            return {"ok": False, "error": "Seat already booked"}

        card = DB.cards.get(card_number)
        fare = DB.buses[bus_id]["fare"]

        if not card or not card["valid"] or card["balance"] < fare:
            return {"ok": False, "error": "Payment declined due to insufficient funds."}

        pnr = DB.create_booking(bus_id, travel_date, seat_number, passenger_name, age, gender, contact, fare)
        booking = DB.bookings[pnr]
        bus = DB.buses[bus_id]

        return {
            "ok": True,
            "booking": {
                "pnr": pnr,
                "passenger_name": booking["passenger_name"],
                "seat_number": booking["seat_number"],
                "bus_name": bus["name"],
                "travel_date": booking["travel_date"],
                "route": bus["route"],
                "status": booking["status"],
                "fare": booking["fare"]
            }
        }


class Database:
    """Direct DB-layer access, for verifying what was really stored."""

    @staticmethod
    def db_get_user(email):
        user = DB.users.get(email)
        return dict(user) if user else None

    @staticmethod
    def db_get_buses(source, destination):
        results = []
        for bus in DB.buses.values():
            if _match_route(bus["route"], source, destination):
                results.append(dict(bus))
        return results

    @staticmethod
    def db_get_seat_status(bus_id, seat_number, travel_date):
        return "occupied" if DB.is_seat_occupied(bus_id, seat_number, travel_date) else "available"

    @staticmethod
    def db_get_booking(pnr):
        booking = DB.bookings.get(pnr)
        return dict(booking) if booking else None

    @staticmethod
    def db_get_all_bookings():
        return [dict(b) for b in DB.bookings.values()]

    @staticmethod
    def db_delete_booking(pnr):
        return DB.delete_booking(pnr)


